get_clients.beforeRequest:
const perPage = inputs.per_page;
if (perPage !== undefined && perPage !== '') {
  const count = parseInt(perPage, 10);
  if (!(Number.isInteger(count) && count >= 1 && count <= 2000)) throw new Error("{\n  \"errors\": {\n    \"per_page\": \"Per Page must be a number between 1 and 2000.\"\n  }\n}");
}
const encode = (text) => encodeURIComponent(text).replace(/%20/g, '+').replace(/[!'()~]/g, (character) => '%' + character.charCodeAt(0).toString(16).toUpperCase());
const pairs = Object.entries(request.query).filter(([, value]) => value.trim() !== '').map(([name, value]) => encode(name) + '=' + encode(value));
if (pairs.length) request.url += '?' + pairs.join('&');
request.query = {};
return request;

